#!/usr/bin/env node
/**
 * sync-guide-translations — writes the id → German-twin loader map for the guide
 * articles (ADR-0018).
 *
 * Every design-system guide ships an English canonical component
 * (`src/app/dev/articles/<id>/<id>-article.component.ts`) and, once translated, a
 * German twin beside it (`<id>-article.de.component.ts`) that extends the English
 * class. The route renders the twin when the base language is `de`. Which guides
 * HAVE a twin is read off the disk here and written to ONE generated file,
 * `src/app/dev/articles/guide-translations.generated.ts`, so translators working
 * on different guides in parallel never edit a shared file by hand: each adds its
 * own twin, and whoever runs this script afterwards picks all of them up.
 *
 * A twin must export exactly one class whose name ends in `ArticleDeComponent`;
 * the file name's id must be a registry id. Both are checked here (exit 1), so a
 * typo fails before the build does.
 *
 * Usage:  node scripts/sync-guide-translations.mjs           # (re)write the map
 *         node scripts/sync-guide-translations.mjs --check   # exit 1 if stale
 *
 * `check-guide-translations.mjs` imports `renderLoaderMap()` and fails while the
 * file on disk differs from it, so a forgotten sync is caught by build:verify.
 * Dependency-free (Node core only).
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const ARTICLES_DIR = path.join(ROOT, 'src', 'app', 'dev', 'articles');
export const GENERATED_FILE = path.join(ARTICLES_DIR, 'guide-translations.generated.ts');
const REGISTRY_FILE = path.join(ARTICLES_DIR, 'article-registry.ts');

/** Registry ids, read as text (article-registry.ts PARSER CONTRACT). */
export function registryIds() {
  const src = fs.readFileSync(REGISTRY_FILE, 'utf8');
  return [...src.matchAll(/^ {4}id: '([^']+)',$/gm)].map((m) => m[1]);
}

/**
 * Every German twin on disk: `{ id, file, rel, className }`, sorted by id.
 * Problems (unknown id, no or several exported classes) are returned, not thrown.
 */
export function findTwins() {
  const ids = new Set(registryIds());
  const twins = [];
  const problems = [];
  for (const dir of fs.readdirSync(ARTICLES_DIR, { withFileTypes: true })) {
    if (!dir.isDirectory()) continue;
    for (const name of fs.readdirSync(path.join(ARTICLES_DIR, dir.name))) {
      const m = /^(.+)-article\.de\.component\.ts$/.exec(name);
      if (!m) continue;
      const rel = `${dir.name}/${name}`;
      if (m[1] !== dir.name || !ids.has(m[1])) {
        problems.push(
          `${rel}: "${m[1]}" is not a registry id in its own folder (expected <id>/<id>-article.de.component.ts).`,
        );
        continue;
      }
      const src = fs.readFileSync(path.join(ARTICLES_DIR, dir.name, name), 'utf8');
      const classes = [...src.matchAll(/^export class (\w+ArticleDeComponent)\b/gm)].map((c) => c[1]);
      if (classes.length !== 1) {
        problems.push(`${rel}: expected exactly one "export class <Name>ArticleDeComponent", found ${classes.length}.`);
        continue;
      }
      twins.push({ id: m[1], file: path.join(ARTICLES_DIR, dir.name, name), rel, className: classes[0] });
    }
  }
  twins.sort((a, b) => a.id.localeCompare(b.id));
  return { twins, problems };
}

/** The generated TypeScript for a list of twins (stable, so `--check` can diff it). */
export function renderLoaderMap(twins) {
  const key = (id) => (/^[a-z][a-z0-9]*$/.test(id) ? id : `'${id}'`);
  const entries = twins.map(
    (t) => `  ${key(t.id)}: () => import('./${t.rel.replace(/\.ts$/, '')}').then((m) => m.${t.className}),`,
  );
  return [
    '// GENERATED by scripts/sync-guide-translations.mjs from the *-article.de.component.ts files on',
    '// disk — do not edit by hand. Run `node scripts/sync-guide-translations.mjs` after adding,',
    '// renaming or deleting a German twin; check-guide-translations.mjs fails while this is stale.',
    "import type { Type } from '@angular/core';",
    '',
    '/** Guide id → lazy loader of its German twin (ADR-0018). A guide without an entry renders in English. */',
    '// prettier-ignore',
    'export const germanGuideLoaders: Readonly<Record<string, () => Promise<Type<unknown>>>> = {',
    ...entries,
    '};',
    '',
  ].join('\n');
}

function main() {
  const { twins, problems } = findTwins();
  for (const p of problems) console.error(`FAIL  ${p}`);
  if (problems.length) process.exit(1);
  const next = renderLoaderMap(twins);
  const current = fs.existsSync(GENERATED_FILE) ? fs.readFileSync(GENERATED_FILE, 'utf8').replace(/\r\n/g, '\n') : '';
  const rel = path.relative(ROOT, GENERATED_FILE).replace(/\\/g, '/');
  if (process.argv.includes('--check')) {
    if (current !== next) {
      console.error(`FAIL  ${rel} is stale — run: node scripts/sync-guide-translations.mjs`);
      process.exit(1);
    }
    console.log(`ok    ${rel} is current (${twins.length} German twin(s)).`);
    return;
  }
  if (current === next) {
    console.log(`ok    ${rel} already current (${twins.length} German twin(s)).`);
    return;
  }
  fs.writeFileSync(GENERATED_FILE, next);
  console.log(`wrote ${rel} (${twins.length} German twin(s): ${twins.map((t) => t.id).join(', ') || 'none'}).`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
